CREATE POLICY customer_payment_outbox_read ON "OutboxEvent" FOR SELECT TO resolve_runtime,resolve_test USING("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND "aggregateType"='CheckoutOperation' AND "eventType" IN ('payment.create','payment.capture') AND EXISTS(SELECT 1 FROM public."CheckoutOperation" c WHERE c.id="OutboxEvent"."aggregateId" AND c."merchantId"="OutboxEvent"."merchantId" AND c."requestedBy"=NULLIF(current_setting('app.user_id',true),'')::uuid));